-- V12: chunk 3 of the Anyagi input (user's Hungarian text, approved 2026-10-17): Hatás of Őselem idézése and Elemi erő idézése,
-- and the descriptions of the four para-elements get their "teremtése" text (Hő, Fagy, Fény, Sötét) with the E scales as lines.
-- Each update applies only while the old value is still stored, so an admin edit is never overwritten.
UPDATE mosaics
SET definition = jsonb_set(definition, '{effect}', '"A varázsló őselemet teremt, amit a kívánt formába zár (formázás). Ez lehet a Hat Iskolaforma egyike, vagy – ha a varázsló bír efféle tudással – valamely Szabálytalan Elemi Forma. Azt, hogy a teremtett őselem meddig marad együtt, a formázás határozza meg. Az ellentétes őselemek gyengítik, akár ki is oltják egymást. A varázslók az őstüzet általában támadásra, az ősvizet általában védekezésre használják, míg a további két őselemhez egyéb céllal, vagy más létsíkok teremtményeivel szemben nyúlnak."'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-oselem-idezese' AND NOT (definition ? 'effect');

UPDATE mosaics
SET definition = jsonb_set(definition, '{inputs}', '[{"id":"paraElement","label":"Paraelem","type":"choice","values":["ho","fagy","feny","setet"],"labels":{"ho":"Elemi hő","fagy":"Elemi hideg","feny":"Elemi fény","setet":"Elemi sötétség"},"descriptions":{"ho":"A tűz és a föld paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt felmelegít az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hideg.\n\nHő teremtése: A varázsló elemi hőt teremt, és a kívánt formába önti. A hőmérséklet az adott formán belül eső területen E-nként 10 °C, függetlenül a természetes hőmérséklettől – akár sebez is, a formán túl ellenben egyáltalán nem érződik. A sebzés körönként 100 °C-nál 1 Sp (sebzés pont), és minden további teljes 20 °C-onként 1 Sp-vel nő.","fagy":"A levegő és a víz paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt lehűt az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hő.\n\nFagy teremtése: A varázsló elemi fagyot teremt, és a kívánt formába foglalja. Az azon belül eső területen hűvös van, fokozott erősítés során fagy jön létre. A hőmérséklet E-nként −10 °C, függetlenül a természetes hőmérséklettől. A sebzés körönként −40 °C-nál jelentkezik (1 Sp), és innen kezdve minden további teljes 20 °C-onként 1 Sp-vel nő.","feny":"A tűz és a levegő paraeleme. Megidézve az adott területen minden pont olyan fényességű lesz, mint az elemi fény erőssége (így az árnyékok eltűnnek). Ellentétes paraeleme az elemi sötétség.\n\nFény teremtése: A varázsló a formázás megszabta területen és alakban elemi fényt teremt. Amennyiben az eredeti fényesség kisebb, akkor ott nem látszik, de a területen mindenhol az adott fényesség lesz minimum, így például az árnyékok eltűnnek.\n\n1 E: gyertya lángja\n2 E: apró gyertya lángja\n3 E: olvasógyertya lángja\n4 E: templomi gyertya lángja\n5 E: mécses lángja\n6 E: fáklya lángja\n7 E: nagy fáklya lángja\n8 E: tábortűz fénye\n9 E: máglya fénye\n10 E: alkonyi fény\n11 E: napfény borús időben\n12 E: fátyolos napfény\n13 E: napsütés\n14 E: déli verőfény\n15+ E: vakító fény\n20+ E: nyitott szem esetén végleges vakság\n\nAz elemi fény azt a területet, ahol érvényesül, a fenti táblázat szerint világítja meg. Ezt a természeti hatások nem befolyásolhatják, kizárólag az elemi sötét! Ha a természetes fény erőssége nagyobb a paraeleménél, akkor ez utóbbinak a jelenlétét észre sem vesszük.","setet":"A víz és a föld paraeleme. Megidézve az adott területen elnyeli a fényt, minden pontban olyan sötét lesz, mint ami az erősségnek megfelel. Ellentétes paraeleme az elemi fény.\n\nSötét teremtése: Hasonló a fény teremtéséhez, úgy szerencsés elképzelni, akár valami negatív, fekete fényt.\n\n1 E: alkonyat\n2 E: telihold\n3 E: fogyóhold\n4 E: újhold\n5 E: csillagos éjszaka\n6 E: borús éjszaka\n7 E: éjszaka kivilágítatlan szobában\n8 E: barlangban\n9 E: vaksötét\n10 E: kráni sötétség\n11+ E: ultra- és infralátás sem működik\n\nA területen, ahol az elemi sötét érvényesül, a fenti táblázat mutatta fényviszonyok érvényesülnek, függetlenül a természetes fénytől. Az elemi sötétet csak az elemi fény világíthatja be, a lámpások és a fáklyák világa vagy akár a nap ehhez nem elegendő, fényük nem is látszik, csak a hőhatásuk érvényesül."}},{"id":"form","label":"Forma","type":"form"}]'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-paraelem-idezese' AND definition #> '{inputs}' = '[{"id":"paraElement","label":"Paraelem","type":"choice","values":["ho","fagy","feny","setet"],"labels":{"ho":"Elemi hő","fagy":"Elemi hideg","feny":"Elemi fény","setet":"Elemi sötétség"},"descriptions":{"ho":"A tűz és a föld paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt felmelegít az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hideg.","fagy":"A levegő és a víz paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt lehűt az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hő.","feny":"A tűz és a levegő paraeleme. Megidézve az adott területen minden pont olyan fényességű lesz, mint az elemi fény erőssége (így az árnyékok eltűnnek). Ellentétes paraeleme az elemi sötétség.","setet":"A víz és a föld paraeleme. Megidézve az adott területen elnyeli a fényt, minden pontban olyan sötét lesz, mint ami az erősségnek megfelel. Ellentétes paraeleme az elemi fény."}},{"id":"form","label":"Forma","type":"form"}]'::jsonb;

UPDATE mosaics
SET definition = jsonb_set(definition, '{effect}', '"A mágikus energiákat felhasználva mozgatni vagy megállítani lehet tárgyakat.\n\nElemi erő teremtése: A varázsló olyan mennyiségű elemi erőt teremt, amely képes megtartani 5 kg súlyú vagy ugyanekkora erővel nekifeszülő tárgyat; avagy semlegesíteni 1 Sp-t, akár egy vért SFÉ-jét. Ez utóbbi leginkább aurára való formázás esetén fordul elő.\n\nálló súly (-): 1 E elemi erő 5 kg-ot tart meg\nséta (×2): 2,5 kg\nfutás (×5): 1 kg\nvágta (×10): 0,5 kg\n\nA súlyváltozás megmutatja, hogy az adott sebességgel haladó tárgy súlya mennyivel számít nagyobbnak, amikor az elemi erőnek ütközik. Az „1 E elemi erő megtart” oszlop megadja, hogy mekkora súlyt képes megtartani 1 E elemi erő, ha az a megadott sebességgel ütközik neki. Ha a súly meghaladja az elemi erő megtartó képességét, az semmilyen hatást nem fejt ki ellene.\n\nAz elemi erőből teremtett nyíl annyi Sp-t (sebzés pontot) sebez, mint amennyi az E-je (ereje), vagyis amennyit a hasonló, valódi anyagból való fegyver is sebezne.\nKitörés esetén az epicentrumban annyi Sp-t sebez, amennyi az E-je, kifelé távolodva negyedméterenként eggyel kevesebbet; nagy erősítés esetén feldönti a tárgyakat, embereket, kicsavarja a fákat, bokrokat.\nAz elemi erőből létrehozott szőnyeg E-nként 5 kg súlyt képes megtartani.\nA fal ugyanennyi súlyú nekifeszülő terhet tart távol, nem engedvén azt át magán."'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-elemi-ero-idezese' AND definition ->> 'effect' = 'A mágikus energiákat felhasználva mozgatni vagy megállítani lehet tárgyakat.';
